<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$clubs=$conn->query("SELECT c.club_name,COUNT(cm.member_id) total_members FROM clubs c LEFT JOIN club_members cm ON cm.club_id=c.club_id GROUP BY c.club_id ORDER BY total_members DESC");$events=$conn->query("SELECT e.event_name,e.event_date,COUNT(r.registration_id) registrations FROM events e LEFT JOIN event_registrations r ON r.event_id=e.event_id GROUP BY e.event_id ORDER BY e.event_date DESC");$att=$conn->query("SELECT e.event_name,SUM(a.status='Present') present,SUM(a.status='Absent') absent FROM events e LEFT JOIN attendance a ON a.event_id=e.event_id GROUP BY e.event_id ORDER BY e.event_date DESC");?>
<!doctype html><html><head><title>Reports</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin Reports</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="analytics.php">Analytics</a><a href="../logout.php">Logout</a></div></nav><div class="container"><h1>Reports</h1><h2>Club Participation</h2><div class="table-box table-wrap"><table class="data-table"><tr><th>Club</th><th>Members</th></tr><?php while($r=$clubs->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['club_name'])?></td><td><?=$r['total_members']?></td></tr><?php endwhile;?></table></div><h2>Event Registrations</h2><div class="table-box table-wrap"><table class="data-table"><tr><th>Event</th><th>Date</th><th>Registrations</th></tr><?php while($r=$events->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['event_name'])?></td><td><?=$r['event_date']?></td><td><?=$r['registrations']?></td></tr><?php endwhile;?></table></div><h2>Attendance</h2><div class="table-box table-wrap"><table class="data-table"><tr><th>Event</th><th>Present</th><th>Absent</th></tr><?php while($r=$att->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['event_name'])?></td><td><?=$r['present']??0?></td><td><?=$r['absent']??0?></td></tr><?php endwhile;?></table></div></div></body></html>
